SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_783
WHERE (kt.kind IN ('episode','tv mini series','tv movie','tv series','video game')) AND (it1.id IN ('16')) AND (mi1.info ILIKE '%ger%') AND (pi.info ILIKE '%29%') AND (it2.id IN ('23')) AND it1.id = non_leaf_783.mi1_info_type_id AND (rt.role IN ('actor','actress','cinematographer','composer','costume designer','director','guest','production designer','writer')) AND it2.id = non_leaf_783.pi_info_type_id;